using ProjetoIntegradorBack.Domain.Entities; using ProjetoIntegradorBack.Domain.Interfaces; using ProjetoIntegradorBack.Infrastructure.Context; using ProjetoIntegradorBack.Shared.Pattern; using Microsoft.EntityFrameworkCore;
namespace ProjetoIntegradorBack.Infrastructure.Repositories;
public class FuncionarioRepository(ProjetoIntegradorBackDbContext context):IFuncionarioRepository{
public async Task<Result<Funcionario>> ObterPorIdAsync(Guid id,CancellationToken ct=default){try{var e=await context.Funcionarios.Include(x=>x.Usuario).FirstOrDefaultAsync(x=>x.Id==id,ct);return e==null?Result<Funcionario>.AsFailure(new Failure(404,"Funcionário não encontrado.")):Result<Funcionario>.AsSuccess(e);}catch(Exception ex){return Result<Funcionario>.AsFailure(new Failure(500,ex.Message));}}
public async Task<Result<IReadOnlyList<Funcionario>>> ListarPorEstabelecimentoAsync(Guid id,CancellationToken ct=default){try{return Result<IReadOnlyList<Funcionario>>.AsSuccess(await context.Funcionarios.Where(x=>x.EstabelecimentoId==id).Include(x=>x.Usuario).ToListAsync(ct));}catch(Exception ex){return Result<IReadOnlyList<Funcionario>>.AsFailure(new Failure(500,ex.Message));}}
public async Task<Result<Funcionario>> AdicionarAsync(Funcionario e,CancellationToken ct=default){try{e.Id=Guid.NewGuid();e.CriadoEm=DateTime.UtcNow;await context.Funcionarios.AddAsync(e,ct);await context.SaveChangesAsync(ct);return Result<Funcionario>.AsSuccess(e);}catch(Exception ex){return Result<Funcionario>.AsFailure(new Failure(500,ex.Message));}}
public async Task<Result<Funcionario>> AtualizarAsync(Funcionario e,CancellationToken ct=default){try{context.Funcionarios.Update(e);await context.SaveChangesAsync(ct);return Result<Funcionario>.AsSuccess(e);}catch(Exception ex){return Result<Funcionario>.AsFailure(new Failure(500,ex.Message));}}
public async Task<Result<string>> AlterarVinculoAsync(Guid id,bool ativo,CancellationToken ct=default){try{var e=await context.Funcionarios.FindAsync(new object[]{id},ct);if(e==null)return Result<string>.AsFailure(new Failure(404,"Funcionário não encontrado."));e.Ativo=ativo;await context.SaveChangesAsync(ct);return Result<string>.AsSuccess("Vínculo atualizado com sucesso.");}catch(Exception ex){return Result<string>.AsFailure(new Failure(500,ex.Message));}}}